    const busca = Object.fromEntries(new URL(url, "http://x").searchParams);
    expect(lerEstado(busca)).toEqual(completo);
  });

  it("sem nada fora do padrão, é só /noite", () => {
    expect(urlDaNoite(ESTADO_INICIAL)).toBe("/noite");
  });

