import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { redirect, useRouter } from "next/navigation";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import NoitePage from "@/app/(app)/noite/page";
import { BotaoVoltar } from "@/features/noite/components/botao-voltar";
import { RecomendacaoNoite } from "@/features/noite/components/recomendacao-noite";
import { obterPreferencias } from "@/features/preferencias/consultas";
import type { PreferenciasInput } from "@/features/preferencias/schema";

vi.mock("next/navigation", () => ({
  redirect: vi.fn((destino: string) => {
    throw new Error(`NEXT_REDIRECT ${destino}`);
  }),
  useRouter: vi.fn(),
}));
vi.mock("@/features/auth/sessao", () => ({
  exigirUsuario: vi.fn(async () => ({ id: "u-1", email: "a@b.c", nome: "Ana" })),
}));
vi.mock("@/features/preferencias/consultas", () => ({ obterPreferencias: vi.fn() }));
vi.mock("@/features/noite/components/recomendacao-noite", () => ({
  RecomendacaoNoite: vi.fn(() => null),
  EsqueletoNoite: () => null,
}));

const preferencias: PreferenciasInput = {
  generos: [28],
  generosEvitados: [],
  duracao: "media",
  frequencia: "semanal",
  streamings: [],
};

const router = { back: vi.fn(), push: vi.fn() };

beforeEach(() => {
  vi.mocked(obterPreferencias).mockResolvedValue(preferencias);
  vi.mocked(useRouter).mockReturnValue(router as never);
});
afterEach(() => vi.clearAllMocks());

async function abrir(busca: Record<string, string>) {
  render(await NoitePage({ searchParams: Promise.resolve(busca) } as PageProps<"/noite">));
}

/** Rótulo e destino de cada cartão de resposta. */
function cartoes() {
  return within(screen.getByRole("list"))
    .getAllByRole("link")
    .map((link) => [link.textContent, link.getAttribute("href")]);
}

describe("página /noite: perguntas", () => {
  it("sem respostas, pergunta o humor com um cartão por resposta", async () => {
    expect(screen.getByRole("heading", { level: 1 })).toHaveTextContent(
      "Como você está se sentindo?",
    );
    expect(cartoes()).toContainEqual(["Cansado", "/noite?humor=cansado&exp=rir"]);
  });

  it("com as três respostas, pede a recomendação da rodada com o perfil", async () => {
    await abrir({ humor: "cansado", exp: "rir", com: "a-dois", trocas: "2", vistos: "7,9" });

    expect(screen.queryByRole("heading")).not.toBeInTheDocument();
    expect(vi.mocked(RecomendacaoNoite).mock.calls[0]![0]).toEqual({
      respostas: { humor: "cansado", experiencia: "rir", companhia: "a-dois" },
      estado: expect.objectContaining({ trocas: 2, vistos: [7, 9] }),
      perfil: preferencias,
    });
  });

  it("sem preferências, manda para o onboarding", async () => {
    vi.mocked(obterPreferencias).mockResolvedValue(null);

    await expect(abrir({})).rejects.toThrow("NEXT_REDIRECT /onboarding");
    expect(redirect).toHaveBeenCalledWith("/onboarding");
  });
});

describe("BotaoVoltar", () => {
    expect(screen.queryByRole("button", { name: "Vou ver esse!" })).not.toBeInTheDocument();
  });
});

describe("RecomendacaoNoite", () => {
  beforeEach(() => {
    vi.mocked(obterNoite).mockResolvedValue(null);
  });

  it("busca a rodada com as respostas, o estado e o perfil, e mostra o destaque", async () => {
    vi.mocked(obterNoite).mockResolvedValue({ destaque: daNoite(10), opcoes: [] });

    render(await RecomendacaoNoite({ respostas, estado: ESTADO_INICIAL, perfil }));

    expect(obterNoite).toHaveBeenCalledExactlyOnceWith(respostas, ESTADO_INICIAL, perfil);
    expect(screen.getByRole("heading", { level: 1 })).toHaveTextContent("Filme 10");
  });

  it("'Esse não' recusa o destaque e as opções e passa para a próxima rodada", async () => {
    vi.mocked(obterNoite).mockResolvedValue({
      destaque: daNoite(10),
      opcoes: [daNoite(11), daNoite(12)],
    });
    const estado = { ...ESTADO_INICIAL, respostas, vistos: [5], trocas: 1 };
    render(await RecomendacaoNoite({ respostas, estado, perfil }));

    await userEvent.click(screen.getByRole("button", { name: "Esse não" }));
    await userEvent.click(screen.getByRole("button", { name: "Outro" }));

    expect(router.push).toHaveBeenCalledExactlyOnceWith(
      "/noite?humor=cansado&exp=rir&com=a-dois&vistos=5,10,11,12&trocas=2",
    );
  });

  it("sem filme, diz que não achou nada e oferece refazer as perguntas", async () => {
    render(await RecomendacaoNoite({ respostas, estado: ESTADO_INICIAL, perfil }));

    expect(screen.getByRole("heading", { level: 1 })).toHaveTextContent(
      "Não achamos nada para essa noite",
    );
    expect(screen.getByRole("link", { name: "Refazer as perguntas" })).toHaveAttribute(
      "href",
      "/noite",
    );
  });

  it("deixa o erro do TMDB subir para a página de erro", async () => {
    vi.mocked(obterNoite).mockRejectedValue(new Error("TMDB fora"));

    await expect(RecomendacaoNoite({ respostas, estado: ESTADO_INICIAL, perfil })).rejects.toThrow(
      "TMDB fora",
    );
  });

  it("manda ao navegador só os campos da tela", () => {
    expect(paraTela(daNoite(10))).toEqual(naTela({ titulo: "Filme 10" }));
  });
});

